namespace Lifestone.Client.Options;

public static partial class OptionCatalog
{
    /// <summary>
    /// The autopilot (M5 item 4 a1 and a2, D57): the outer loop over the journey's stations, read by its hosts (slice h1: the headless <c>--scenario=autopilot</c> and the game's <c>--login-check=autopilot</c>); parsed by
    /// src/Lifestone.Client/Session/Autopilot/AutopilotOptions.cs (<c>AutopilotOptions.FromArguments</c>). Append only.
    /// </summary>
    public static OptionGroup Autopilot() => new("Autopilot", "main scene and headless host",
    [
        new("--autopilot-minutes", "M", "The autopilot's duration stop rule: after M minutes of the session clock (0 to 10080, default 0: no such rule) it stops at its next safe point (a fight is asked to stop and ends cleanly; a trip or a death handler in progress finishes first) and writes stop=minutes on its done line. A bad value fails the run."),
        new("--autopilot-level", "L", "The autopilot's level stop rule: when the character level the state holds reaches L (0 to 275, default 0: no such rule) it stops at its next safe point and writes stop=level on its done line. A bad value fails the run."),
        new("--autopilot-trip-after-kills", "N", "Forces one logistics trip after N kills counted from the cycle's start (0 to 100000, default 0: none; M5 D52's live half, the gate uses 5): the fight is asked to stop, the logistics station runs with trigger=forced (recall home, the vendors, the experience, the recall back) and the cycle ends. Once a run; the counters' own trips are not affected. A bad value fails the run."),
        new("--autopilot-test-death", "[on|off]", "The gate's scripted death (default off; M4 D37): once, at the first fight after its first kill, the fight is asked to stop and the journey's death station runs (the mage takes its armour off and lies down among the creatures, respawns and the death handler brings the corpse back without its own fight), then the autopilot goes back to its fight; the cycle ends with the death. A bad value fails the run."),
        new("--autopilot-watchdog-scale", "F", "The factor on every autopilot watchdog bound (0.01 to 100, default 1; M5 item 4 a2). A state over its bound (Lifestone's own: the known state 90 s, the buff 300, the travel 150, the fight 900 without a kill, the trip and the death 900) is logged as 'watchdog: <state> over <n> s' and recovered by the recall home and the known state. A bad value fails the run."),
        new("--autopilot-watchdog-recoveries", "N", "How many watchdog trips a cycle the autopilot recovers (0 to 20, default 2); the next trip in the cycle stops the run with stop=watchdog:<state> and ok=no. A bad value fails the run."),
        new("--autopilot-reconnect-waits", "S,S,...", "The seconds the autopilot waits before each try to reconnect a dropped session, one entry a try (1 to 10 entries of 0 to 600, default 5,15,30,60,120; Lifestone's own). ACE drops a silent client after 60 s, so the default sums to 230 s; the last failed try stops the run with stop=reconnect-failed and ok=no. A bad value fails the run."),
        new("--autopilot-test-interrupt-at", "S", "The gate's scripted hand-off, part one (M5 item 4 h3, D58; since M5 7 D145 typed, not pressed; the game's play host and --login-check=autopilot only, 0 to 86400, default off): S seconds after the first fight state (M5 4 F3, 4-R10; with --autopilot-test-death, the first fight after the scripted death's cycle, so it lands mid-fight and never in the buff, the trip or the death), /stop is typed into the main chat's entry and sent, the person's own path; the autopilot stops where it stands and the movement keys are the person's (interrupted=1). Logged as 'test-interrupt: typed /stop in the <state> state'. A bad value fails the run."),
        new("--autopilot-test-handback-after", "S", "The gate's scripted hand-off, part two (M5 item 4 h3, D58; since M5 7 D145 typed, not pressed; needs --autopilot-test-interrupt-at, 0 to 86400, default off): S seconds after the scripted /stop, /auto is typed into the main chat's entry and sent, and the loop resumes from the state it finds (resumed=1; a hand-back still waits for a held movement key, logged 'hand-back: waiting for the movement key to be released'). Logged as 'test-handback: typed /auto'. A bad value fails the run."),
        new("--autopilot-start", "[on|off]", "The unattended start (M5 item 7 s1, m5-autopilot-start; the game's play host only, default off): once the character is in the world and the host's own rule allows it (BSD Mage only, as a press does) the dial starts ONCE as /auto does and logs 'autopilot: started by --autopilot-start'; it never starts again by itself (after a /stop or Done, /auto in the chat decides; M5 7 D145). With it, when the dial ends by its own stop rule (stop=minutes or stop=level) or by a failure (ok=no) the game logs off, quits after the done line with exit code 0 for ok=yes and 1 otherwise, and logs that decision in one line; a person's /stop keeps the game open. The run's stop rules and bounds (--autopilot-minutes, --autopilot-level, the watchdog and reconnect options) come from the same command line."),
        new("--autopilot-stop-file", "PATH", "A clean stop for the soak from outside (M5 7 F18; the game's play host only, default none): the host looks for the file every 5 s (nothing is read in between); when it exists the dial is asked to stop (request 'stop-file'), and the autopilot casts the recall home first when the mage is away from home. With --autopilot-start the run then ends as the unattended end does (log off at home, quit with exit code 0 for ok=yes); without it the game stays open. The path is the output-path rule's: relative to the repository, never under src/ or tests/ (tools/soak.ps1 passes <run folder>/stop, and its -Stop switch writes that file). A path that cannot be used is reported by name and no file is watched."),
        new("--autopilot-checkpoint-dir", "DIR", "The headless host's autopilot checkpoint folder (M5 item 4 h3; --scenario=autopilot only; default an 'autopilot' folder beside the run's recording): one file a character (bsd-mage.json), written on every state change and on exit, read at the next start so a restart carries the totals and the minutes used. A path under src/ or tests/ is refused. The game keeps its own under the user data (user://autopilot)."),
        new("--autopilot-control-drill", "DIR", "The live proof of taking the controls and giving them back (M5 7 D145; the game's play host only, with --autopilot-start; default off; tools/soak.ps1 -ControlDrill passes <run folder>/control-drill): through the game's own input path (Move Forward's key through Godot's input, lines typed into the main chat's entry; no server cheat, no key reaches the operating system), (a) mid-fight Move Forward held 1 s does nothing and the notice shows, (b) /stop mid-fight stops it where it stands and Move Forward then moves it, (c) a bad state (about 10 m off the spot, peace, the wielded caster moved into a side pack as a person's drag sends it) then /auto, and the next kill, (d) on the next town trip /stop mid-walk, /auto 5 s later, and the trip's end. Every line starts 'control drill:'; each step ends in one 'control drill: step=<a|b1|b2|c1|c2|d1|d2|d3> verdict=pass|fail ...' line that reads the state then, and saves control-drill-<step>.png into DIR (the window's own size). Step d needs a trip: --autopilot-trip-after-kills. Resolved from the repository root by the output-path rule (never inside src/ or tests/). The frames are screenshots of the user's own retail render and are never committed."),
        new("--autopilot-steer-orders", "[on|off]", "The steer desk takes command orders (the game's play host only, default off): an inbox order of kind command with args {\"line\": \"trip\"} (any line the chat's orders take: trip, rebuff [self|bot], quest <key>, ladder, home, den, pause, resume, stop, status, help, queue, cancel, clear; a trailing 'then idle' holds her at home after it), trip, or run_quest with args {\"key\": ...} goes to the same command runner as the chat's /trip, /rebuff, /quest and /ladder; its report follows the command (running while it is queued, waits for its safe point and acts; then done, failed or refused by name). Observe-only does not refuse them while this is on; off, they are refused by name (orders-off, or observe-only). tools\\order.ps1 drops one and prints its report. docs/commands.md lists every command."),
        new("--autopilot-steer-observe", "[on|off]", "Observe-only for the steer desk (the game's play host only, default off): the desk answers the probes ping, sheet and capture and refuses every other order by name (observe-only), logged, whatever would otherwise have allowed it. status.json says observe_only."),
        new("--autopilot-steer-dir", "DIR", "The steer desk's run folder (the game's play host only, default none: no desk, and nothing changes): the file-based way an outside process asks the autopilot for something. The folder holds inbox (orders), taken, outbox (each order's report), status.json (the live picture, every 2 s and on a change), events.ndjson and sheets. This build answers the probes ping, sheet (including recent, the last 15 minutes of game stats) and capture (a screenshot in shots, at most one every 10 s), the controls, and with --autopilot-steer-orders the command orders (command, trip, run_quest: the chat's orders, docs/commands.md); every other order is refused by name (not-built). The desk opens only against a server on this computer. Resolved from the repository root by the output-path rule (never inside src/ or tests/); a path that cannot be used is reported by name and no desk is opened."),
        new("--autopilot-job", "den|level-up", "The autopilot's job (M6 item 0 a4; default den: M5's den job, BSD Mage on the journey's ground, unchanged). level-up is the level up job's first form: the character is the ladder's (Winnie on the account test, M6 D7; the host's start rule plays Winnie in this job only and BSD Mage in den only), and at each cycle's start the ground is the war mage's ladder rung for the character's own level (PropertyInt 25): a quest rung stops the run with stop=rung-quest:<rung>, a rung whose profile is not written with stop=rung-pending:<rung>, a rung whose ground the fight cannot walk with stop=rung-unfightable:<rung> (the fight's own ground rule), a level past the ladder's top with stop=ladder-top, and a level that has reached the rung's move-on level (its top + 1) with stop=rung-moved:<next rung> (ok=yes: the host starts the next run on the next rung's ground). The cycle names the bolt level cap (the rung's plan value), the target band (the character's level + 5) and the buff lines the spellbook lacks, each once. Every cycle and the done line add a report-only [ladder] line: level rung ground kills xp_per_h deaths scrolls_bought spent_xp quests_done granted walk_s and the move-on rule's kills-an-hour floor and casts-a-kill ceiling (D27). A bad value fails the run."),
        new("--autopilot-climber", "NAME", "Which climber the level up job plays (default Winnie; Qwinnie is the local model's own, on the account qwinnie). A name that is not a climber fails the run."),
        new("--autopilot-task", "job|quest:KEY|errand|den-run", "The task the autopilot runs inside the install job (M6 6 MA; default job: the job's own loop, level up or the den). quest:KEY is one quest of the catalog, done once from home (a quest that is not due ends the run at once); errand is one forced logistics trip. The menu and /auto choose a task at run time; this is the same choice from the command line. An unknown value fails the run."),
        new("--autopilot-buff-bot", "[on|off]", "The autopilot's stop at the buff bot (M6 item 14, D124-D127; default on): at home in Holtburg, when a line of the bot's profile is down or has under 45 minutes left, the character walks to the bot by the lifestone, tells it the profile's word and reads each level VII buff as it lands, before its own buff pass, which then casts only what the bot does not cover. off: the character buffs itself alone, as before item 14. The bot is the server mod's (LIFESTONE_BUFF_BOT=off keeps it out of the world; an absent bot is logged and the character's own pass runs). Every [ladder] line says buffbot=on or off. A bad value fails the run."),
        new("--autopilot-rung-holds", "hold|report", "Whether anything but her level holds a rung of the ladder (M6 holding at 60, the owner 2026-11-20: the only thing that should stop her is her level; default hold). report: the rungs' gates, a ground's approach checks (survival and the crossing's mana cost) and the vitae burn's hold are read and logged, and the travel leg still measures a crossing and logs it, but none of them holds a rung, gives a crossing up or recalls her on a projection: the ladder's band and the portals' own level limits decide. Her buffs are still cast before every trip, and the fights' own retreats (the mana line, the losing race) are unchanged. Grounds named by --autopilot-hold-grounds stay held."),
        new("--autopilot-villa", "[on|off]","The villa track in the level up job (M6 villa, the owner 2026-11-15: packs, and then ideally a villa; default on). At each town trip's boundary the villa schedule runs at most one of each step, by rule: the rent within 3 days of its period's end; the purchase of a villa of the block slumlordvilla1401-1440 (2,000,000 pyreals or trade notes, 5 Writs of Refuge, 1 Crude Lockpick) with no house owned and the price in the packs (at once: the server mod turns ACE's 15-day account age off; see --autopilot-villa-account-age); one Crude Lockpick at the Merchant east of Holtburg while none is held; the minor stones to writs at Holtburg's Agent of the Arcanum in pairs; the stone fetches from the walkable caves the writ pace asks for (the 7 writs for the price and the first rent: with the purchase open, a fetch from each cave its hour's timer allows at every town trip; under the account age, spread evenly over the time left before the opening less a day, every boundary once behind); the kept finds into the villa's chests (held while TODO(villa-house-portal-walk) stands). Nothing runs while the house status is unread (one HouseQuery a run). A step that fails is not called again that run. Every cycle line ends villa=off or villa=on,<phase>,writs:held/wanted,stones:n,half:yes|no,pyreals:held/price,per_h:<the money's trend an hour>. off: none of it. A bad value fails the run."),
        new("--autopilot-villa-account-age", "off|ace", "The account age the villa schedule and the purchase read (M6 villa, the owner 2026-11-16: a house needs no account age; default off: the account may buy at once, as the server mod sets ACE's house_15day_account false at every start). ace: retail's 15 days, for a server started with LIFESTONE_ACE_HOUSE_ACCOUNT_AGE=ace: the climber's account may buy from 2026-11-24 22:51:38 UTC, the writs are paced to that date less a day, and the purchase is refused before it (too-early). A bad value fails the run."),
        new("--autopilot-every-spell", "[on|off]", "The every-spell rule in the level up job (M6 14, the owner 2026-11-16: with the money she has, she buys every spell, eventually when affordable; default on). On the town trips she already makes, beyond the spell plan and the job's needs, she buys and reads every spell a scrivener of the catalog's towns sells (the whole create lists, Grounds/scrivener-stock.json) in a school she has trained, at its highest level that casts at the plan's chance on her standing skill (the buff bar for a beneficial spell, the combat bar for the rest; ACE asks no lower level first). The order: each element's bolt, Harm Other, Drain Health Other and the war shapes the picker offers; then her buffs and the protections the fights read; then the rest, the cheapest first, the lines the buff bot casts for her last. The purse is her coin and the faces of her trade notes above a reserve derived live: her supplies and town stock at their keeps, the buff bot's fee from its level, the villa's price and first rent while that track is on, and the trip's planned needs (the spell plan's scrolls, the focus, the leather set); nothing of her kit is sold to pay. Home scrolls are bought on the home walk, the V and VI by the Town Network, batched by vendor, within the pack's free slots above the loot's floor and under the burden line. Each buy and read is check, act, check (the spellbook's update is the proof); a scroll ACE refuses to teach is kept, logged loud and never bought again. Every pick and refusal is logged with its numbers (every_spell: lines). Every cycle line ends every_spell=off or every_spell=on,wanted:n,buy:n,learned:n,refused:n,reserve:n,next:<spell>@<price> (on,unread before the first trip). off: none of it. A bad value fails the run."),
        new("--autopilot-player-rules", "[on|off]", "The player's rules on the automation (M6 item 15; default on; read by the session, so every automated path passes it: the fight, the buff cycle, the vitals keeper, the death handler, the recalls, the journey's legs). on: every spell an automation action casts is on one of the character's spell bars, and one that is on none is put there first as a player puts it (AddSpellFavorite, logged by name: tab I creature buffs, II the fight, III heals and drains, IV life buffs, V item enchantments, VI travel and utility; a higher level takes its line's lower level's place); every potion and tincture it drinks is on the shortcut bar while any is held (AddShortcut; the keys 1 to 8 by vital) and the drink is that shortcut's item; the spellcasting panel shows the cast spell's tab with the spell selected. A cast or drink that is still on no bar is refused by name. off: the automation casts and drinks without the bars, as before. A bad value fails the run."),
        new("--autopilot-start-quest", "KEY", "A quest started at once in the level up job (M6 14, the owner's ruling, 2026-11-16: start the quest on request (a way to trigger the autopilot to start the quest at once); default off). At the run's start, after its first audit, trip and buff pass at home, the job runs the errand of the quest KEY (a key of the quest catalog, for example atlan-wand) from home, with no trip from kills; then the ladder goes on as usual. When the errand ends, done, failed or cut, the ladder resumes and the errand's own retry and resume rules apply. Its level gate (a ladder band or a level range), a done once-quest, its timer and a quest selection that leaves it out are refusals by name ('autopilot quest: start-quest: refused: ...'). The level up job's own loop only (--autopilot-job level-up, --autopilot-task job). In the chat: /auto level-up quest KEY."),
        new("--autopilot-ladder-quests", "[on|off|KEY,...]", "The level up job's quests (M6 item 14, the sprint; default on: the ladder as before, every ladder errand and trophy turn-in and no kill task). off: a sprint to the level as fast as the grounds give it: no quest errand is run from home (the ladder errands of the quest files' ladder bands), no held trophy is turned in, the fight wants no trophy (no holder is pulled, no trophy is kept aside) and no rung is entered for a trophy job; each quest skipped is logged once a run by name ('autopilot quest: key=<key>: skipped: --autopilot-ladder-quests=off'). KEY,...: a selection (M6 14 guard task) that runs only the quests it names, by the quest catalog's keys or the group 'tusks' (every tusk turn-in at Brighteyes, the catalog's tusk-* keys), the rest off and each skipped one logged once a run by name; a kill task it names (tusker-guard-kill-task) is run by the level up job: the talk that arms it from home, its hunt in place of her rung's ground while the server's counter is armed, and its turn-in when the counter reads complete (example: tusks,tusker-guard-kill-task). The ladder's first rungs that are quests, the Training Academy and the Pathwarden chest (levels 1 to 4: her first gear), stay as they are in every setting, and so does a quest asked by name (--autopilot-task quest:KEY). A bad value (an unknown key, a word twice, on or off inside a list) fails the run."),
        new("--autopilot-buff-bot-word", "WORD", "The word the character tells the buff bot (M6 item 14; default all: every buff a level VII bot casts on another, 28 lines: the tuskers' 19 and then the six other elemental protections, Magic Resistance, Impregnability and Arcane Enlightenment). tusker (or tuskers) is the profile of before: 19 lines with Bludgeoning Protection alone. Every rule of the stop reads the profile the word asks for: the stop is due when a line of it is down or has under 45 minutes left and is done when every line of it is up, the trip home from the field is called by the least seconds any of its lines has left, and the character buys, keeps and reads no Self scroll of a line it holds. The stop's verdict says word= lines= landed=. Read only while --autopilot-buff-bot is on. A word the bot does not know fails the run."),
        new("--autopilot-quest-own-kill-loop", "[on|off]", "The quest steps' own kill loop (M6 16 Q8; default off). off: a quest step's kill and the defence on a quest walk cast through the skirmish, the travel leg's fight-back: the step's creature is still sought and walked to by the step (its mana first, the walk into 15 m, one walk for a clear line), then the bolt is chosen for each target by its element, a bolt the target is out of reach of gives way to Harm Other or a run past, bolts that come to nothing give way to Harm Other, the dance under fire keeps the way out's reserve (Lifestone Recall and a heal), and a fight that cannot go on ends the step at once by name (kill: no mana, kill: timeout, kill: mana-line) instead of waiting up to 90 s for the mana. on: the old loop of before (its own cast, its 90 s wait for the mana). Kept for the skirmish's first live gate on the errands. A bad value fails the run."),
        new("--autopilot-den-run-rehearse", "[on|off]", "The den run's rehearsal (M6 item 14; default off; names the den run's order by itself). The order's trip, buff bot, own pass and check before run as for the den run; the road is then run only as far as Danby's Outpost: the hops through the Town Network, then a run-only straight run from Danby's drop toward the Desert March Portal that ends 25 m short of it (the portal is not used), Lifestone Recall home, and the stop 'den-run:rehearsed' with the metres, the seconds, the attackers and the drinks of each leg. The first den run (2026-11-13) was called off with none of it tried before: this is the trial."),
        new("--autopilot-den-run", "[on|off]", "The den run, by order (M6 item 14, the owner 2026-11-12; default off). With it the level up job (--autopilot-job level-up) does one thing and stops: the trip home with its sale and the scrolls of Primary Portal Tie and Primary Portal Recall, the stop at the buff bot, the character's own buff pass, then one run to the Black Spawn Den's entrance at 60.0S 57.6W by the Town Network, Danby's Outpost, the Desert March Portal and the Black Hill portal, never stopping to fight; into the den at once, one minute inside, out by its Surface Portal, Primary Portal Tie at the entrance, and Lifestone Recall home. The run stops 'den-run:tied' (ok) or by the failure's name. It refuses to start, by name, under level 40, with the buff bot off or told another word than all, with a line of the bot's profile down or under 45 minutes, with the book short of Primary Portal Tie, Primary Portal Recall or Lifestone Recall, or with the burden at 100% of the capacity or over. One attempt an order: a death on the way ends the run ('den-run:died:<leg>') and the corpse is not fetched. The same as --autopilot-task den-run. A bad value fails the run."),
        new("--autopilot-trial-ground", "KEY", "A trial of a later rung's ground (M6 item 14, the owner 2026-11-13; default off; the level up job's own loop only). The level up job hunts the ground KEY in place of the ladder's own rung for --autopilot-trial-minutes of fight time counted from her first kill there, then returns to the ladder's rung through a normal rung change (rung-moved:<rung>). The trial's rules, read at its start: KEY is a ground of a rung after her own, or one of that rung's alternates (war-mage.json); its entry portal's level range admits her; and its rung's gate holds, or for a rung with none the last gate before it (the Abode's, the Cave's lines), read whole and live at the way out before she leaves home. A rule that fails refuses the trial by name ('ladder: trial: refused: ...') and the ladder goes on as usual. The route is the ground's own (travel-routes.json); a supply trip and the buff bot's trip come back to it; a death during the trial ends it and the ladder resumes its own rung after the recovery. Every line says 'ladder: trial: ' (start, refused, return n=, first kill, end), and the [ladder] line of a cycle fought under the trial says trial=KEY. A new process starts the trial again. A ground that is not a hunting ground fails the run."),
        new("--autopilot-hold-grounds", "KEY[,KEY]", "Grounds held for the session (M6 14; default none; the level up job). Each ground named is read by every way out as a crossing given up earlier ('ladder: approach cost at the way out: approach-abandoned: ... held for the session by --autopilot-hold-grounds'), so the ladder never leaves for it: it hunts the rung's other ground or the rung before it. For a ground found unsafe live (a death on its first visit) until its cause is fixed. A key that is not a hunting ground fails the run."),
        new("--autopilot-trial-minutes", "N", "The trial's minutes of fight time, counted from her first kill on the trial's ground (M6 item 14; default 30, more than 0 and at most 1440). Fight time only: the trips, the bot, the passes and a death between fights do not count. Read only with --autopilot-trial-ground; given alone it fails the run."),
        new("--autopilot-hour-load", "[on|off]", "The hour load (M6 14, the owner 2026-11-16; default on). On a comfortable ground (no jump, home by Lifestone Recall, no trial, no death, retreat or survival leave this cycle, and the peak incoming damage a second covered by the heal she sustains, each read logged as 'hour load: comfort read:') the loot's load line rises from her burden at the cycle's first fight frame to --autopilot-hour-load-top at the hour (or at the buff bot's trip, if sooner), and the trip is due at the hour (the logistics cause 'hour'; every other trip cause wins). Elsewhere the line stays the ground's (100% by default; never over it on a ground with jumps). The swap of sell loot for a better value per burden runs on every ground whatever this says. The cycle line marks it: hour_load=off|held|rose:<line>|hour:<line>."),
        new("--autopilot-hour-load-minutes", "M", "The hour load's cycle length in minutes of fighting (M6 14; more than 0 and at most 1440, default 60). A bad value fails the run."),
        new("--autopilot-hour-load-top", "P", "The hour load's line at the hour, in percent of the capacity (M6 14; 100 to 199, default 150; held to the ground's burden trip line). ACE's load modifier is 2 - load from 100% and 0 from 200% (EncumbranceSystem.GetBurdenMod): at 150% the modifier is 0.5, which scales the run skill's part of her run rate (MovementSystem.GetRunRate) and her melee and missile defense (Creature_Combat.GetEffectiveDefenseSkill). A bad value fails the run."),
        new("--walk-awareness", "pinned|own", "Which awareness range the session's walks keep off a hostile creature (M6 item 16 E1f; default own since M6 16 Q3; read by the session, so every walk of the automation passes it: the fight's walks, the travel legs, the quest steps). pinned: the range pinned for the creature's kind (74 kinds), else ACE's default of 18 m, as every walk kept before. own: the kind's own VisualAwarenessRange from the world database (the bestiary's creature-behaviour table), times the server's mob_awareness_range; a kind the tables do not hold keeps its pin, else the default. Of the 47 creature kinds the ground profiles name, 37 have a range of their own that is not the 18 m they are read at: 30 notice farther (to 30 m) and 7 less far. In both modes the walk reports what the other range would have changed and decides nothing by it: once a session for each kind seen whose two ranges differ ('awareness-shadow: <name> (class N): the walk keeps R1 m, its own range gives R2 m'), and once a travel leg the creatures passed inside their own range and outside the pinned radius, how many of them were then among her attackers, and the closest such pass ('awareness-shadow: the <leg> leg to <label>: ... mode= passed= attackers= closest_m= session_legs= session_passed= session_attackers='). A bad value is reported and the option keeps own."),
    ], OptionScenes.Main | OptionScenes.Headless);
}
